def log(msg: str):
    print(f"[CENTINELA] {msg}", flush=True)


def run_cmd(cmd: List[str], check: bool = True) -> str:
    """Ejecuta un comando de terminal y retorna la salida estándar limpia."""
    res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding="utf-8")
    if check and res.returncode != 0:
        raise RuntimeError(f"Error ejecutando {' '.join(cmd)}: {res.stderr.strip()}")
    return res.stdout.strip()


def gh_graphql(query: str, variables: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Ejecuta consultas o mutaciones en la API GraphQL de GitHub usando gh CLI."""
    cmd = ["gh", "api", "graphql", "-f", f"query={query}"]
    if variables:
        for k, v in variables.items():
            if isinstance(v, bool):
                cmd.extend(["-F", f"{k}={str(v).lower()}"])
            elif isinstance(v, int):
                cmd.extend(["-F", f"{k}={v}"])
            else:
                cmd.extend(["-F", f"{k}={str(v)}"])
    
    out = run_cmd(cmd)
    try:
        data = json.loads(out)
    except json.JSONDecodeError as e:
        raise RuntimeError(f"Respuesta JSON no válida de GitHub: {out}") from e
    
    if "errors" in data:
        raise RuntimeError(f"Errores GraphQL: {json.dumps(data['errors'], indent=2)}")
    return data.get("data", {})


def detect_language(text: str) -> str:
    """
    Detecta si el texto está principalmente en inglés ('en') o español ('es')
    usando heurísticas de frecuencias léxicas y caracteres típicos.
    """
    t_clean = text.lower()
    
    # Caracteres inequívocamente españoles
    if any(ch in t_clean for ch in ["¿", "¡", "á", "é", "í", "ó", "ú", "ñ"]):
        return "es"
        
    en_words = {"how", "what", "why", "when", "where", "which", "is", "the", "are", "and", "or", "in", "to", "for", "with", "difference", "between", "prevent", "leak", "secret", "tokens", "using", "open", "source"}
    es_words = {"cómo", "como", "qué", "que", "cuál", "cual", "dónde", "donde", "por", "para", "con", "en", "el", "la", "los", "las", "un", "una", "diferencia", "entre", "prevenir", "fuga", "secreto", "usar", "usando", "proyecto"}
    
    tokens = set(re.findall(r"\b[a-záéíóúñ]+\b", t_clean))
    en_score = len(tokens.intersection(en_words))
    es_score = len(tokens.intersection(es_words))
    
    return "en" if en_score > es_score else "es"


def detect_security_or_bug_escalation(title: str, text: str) -> Optional[Tuple[str, str]]:
    """
    Evalúa si la pregunta o reporte involucra una vulnerabilidad crítica o bug que requiera
    escalamiento inmediato a un Issue interno asignado al mantenedor.
    Utiliza expresiones regulares con límites de palabra para evitar falsos positivos.
    Retorna (categoría, motivo) o None.
    """
    combined = (title + " " + text).lower()
    
    security_patterns = [
        r"vulnerabilidad(es)?", r"vulnerabilit(y|ies)", r"exploit(s)?", r"cve-\d+",
        r"sql injection", r"inyecci[oó]n", r"\brce\b", r"remote code execution",
        r"\bxss\b", r"cross-site scripting", r"fuga cr[ií]tica", r"secret exposed",
        r"token leak(ed)?", r"private key leak(ed)?", r"malware", r"compromised",
        r"fallo de seguridad grave"
    ]
    for p in security_patterns:
        if re.search(r"\b" + p + r"\b", combined, re.IGNORECASE):
            return ("security", f"Término de seguridad detectado: '{p}'")
            
    bug_patterns = [
        r"crash total", r"pantalla blanca", r"500 internal server error",
        r"build roto en producci[oó]n", r"memory leak grave", r"infinite loop crash"
    ]
    for b in bug_patterns:
        if re.search(r"\b" + b + r"\b", combined, re.IGNORECASE):
            return ("bug", f"Patrón de fallo crítico detectado: '{b}'")
            
    return None


def escalate_issue_to_github(owner: str, repo: str, disc_number: int, title: str, author: str, comment_url: str, category: str, text: str, dry_run: bool = False) -> Optional[str]:
    """Crea un Issue interno asignado al propietario para atender el reporte escalado."""
    issue_title = f"[{category.upper()}] Escalamiento desde Discusión #{disc_number}: {title}"
    body = f"""### ⚠️ Escalamiento Automático de Discusión #{disc_number}

El Agente Centinela identificó un reporte clasificado como **{category.upper()}** en GitHub Discussions.

- **Discusión Original:** #{disc_number} - {title}
- **Enlace al comentario:** {comment_url}
- **Autor:** @{author}
- **Fecha de Detección:** {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC')}

#### Fragmento del reporte:
> {text[:400]}...

---
*Acción sugerida: Inspeccionar el reporte y validar si requiere parches inmediatos o mitigación en el portafolio.*
"""
    if dry_run:
        log(f"[SIMULACIÓN] Se crearía Issue de escalamiento: '{issue_title}' asignado a @{owner}")
        return f"https://github.com/{owner}/{repo}/issues/simulation-escalate-{disc_number}"
        
    cmd = [
        "gh", "issue", "create",
        "--title", issue_title,
        "--body", body,
        "--label", category,
        "--assignee", owner
    ]
    try:
        issue_url = run_cmd(cmd)
        log(f"Issue de escalamiento creado exitosamente: {issue_url}")
        return issue_url
    except Exception as e:
        log(f"Aviso: no se pudo crear el Issue de escalamiento (posible falta de permisos de issues): {e}")
        return None


def send_level_3_notifications(owner: str, repo: str, disc_number: int, title: str, author: str, comment_url: str, lang: str):
    """
    Nivel 3 de Notificación: Despacha alertas a canales externos (Telegram y/o Discord)
    si los secretos correspondientes están configurados en las variables de entorno.
    """
    # 1. Telegram Webhook
    tg_token = os.environ.get("TELEGRAM_BOT_TOKEN", "").strip()
    tg_chat_id = os.environ.get("TELEGRAM_CHAT_ID", "").strip()
    if tg_token and tg_chat_id:
        try:
            tg_text = (
                f"🤖 *[Agente Centinela - {repo}]*\n\n"
                f"Se atendió la duda de @{author} en la Discusión #{disc_number}:\n"
                f"*{title}*\n\n"
                f"🔗 [Revisar y Validar Respuesta]({comment_url})"
            )
            tg_url = f"https://api.telegram.org/bot{tg_token}/sendMessage"
            payload = json.dumps({
                "chat_id": tg_chat_id,
                "text": tg_text,
                "parse_mode": "Markdown",
                "disable_web_page_preview": False
            }).encode("utf-8")
            req = urllib.request.Request(tg_url, data=payload, headers={"Content-Type": "application/json"}, method="POST")
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status == 200:
                    log("Notificación Nivel 3 (Telegram) despachada con éxito.")
        except Exception as e:
            log(f"Aviso al enviar alerta a Telegram: {e}")
    else:
        log("Telegram Webhook no configurado (TELEGRAM_BOT_TOKEN / TELEGRAM_CHAT_ID omitidos).")

    # 2. Discord Direct Message (Bot DM)
    discord_bot_token = os.environ.get('DISCORD_BOT_TOKEN', '').strip()
    discord_user_id = os.environ.get('DISCORD_USER_ID', '').strip()
    if discord_bot_token and discord_user_id:
        try:
            dm_channel_url = 'https://discord.com/api/v10/users/@me/channels'
            dm_headers = {
                'Authorization': f'Bot {discord_bot_token}',
                'Content-Type': 'application/json',
                'User-Agent': 'CentinelaAgent/1.0'
            }
            dm_payload = json.dumps({'recipient_id': discord_user_id}).encode('utf-8')
            req = urllib.request.Request(dm_channel_url, data=dm_payload, headers=dm_headers, method='POST')
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status in (200, 201):
                    dm_data = json.loads(resp.read().decode('utf-8'))
                    channel_id = dm_data.get('id')
                    if channel_id:
                        msg_url = f'https://discord.com/api/v10/channels/{channel_id}/messages'
                        discord_text = (
                            f'🤖 **[Agente Centinela - {repo}]**\n\n'
                            f'Se atendió la duda de **@{author}** en la Discusión #{disc_number}:\n'
                            f'*{title}*\n\n'
                            f'🔗 **Validar en GitHub:** <{comment_url}>'
                        )
                        msg_payload = json.dumps({'content': discord_text}).encode('utf-8')
                        req_msg = urllib.request.Request(msg_url, data=msg_payload, headers=dm_headers, method='POST')
                        with urllib.request.urlopen(req_msg, timeout=10) as resp_msg:
                            if resp_msg.status in (200, 201):
                                log('Notificación Nivel 3 (Discord DM directo) despachada con éxito.')
        except Exception as e:
            log(f'Aviso al enviar DM a Discord: {e}')
    else:
        log('Discord Bot DM no configurado (DISCORD_BOT_TOKEN o DISCORD_USER_ID omitidos).')

    # 3. Discord Webhook (Canal alternativo)
def write_step_summary(records: List[Dict[str, Any]]):
    """
    Nivel 2 de Notificación: Escribe una tabla ejecutiva en GitHub Actions Step Summary.
    """
    summary_path = os.environ.get("GITHUB_STEP_SUMMARY")
    if not summary_path:
        return
        
    lines = [
        "## 🛡️ Reporte Ejecutivo del Agente Centinela de Discussions",
        f"**Fecha UTC:** {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S')}",
        "",
        "| Discusión | Usuario | Idioma | Escalamiento | Enlace de Validación |",
        "| :--- | :--- | :---: | :---: | :--- |"
    ]
    
    if not records:
        lines.append("| — | — | — | — | *No hubo discusiones pendientes en este ciclo* |")
    else:
        for r in records:
            esc = f"⚠️ {r['escalado']}" if r['escalado'] else "✅ Normal"
            lines.append(f"| #{r['numero']} - {r['titulo']} | @{r['autor']} | {r['idioma'].upper()} | {esc} | [Revisar Respuesta]({r['url']}) |")
            
    try:
        with open(summary_path, "a", encoding="utf-8") as f:
            f.write("\n".join(lines) + "\n")
        log("Nivel 2: Step Summary de GitHub Actions generado exitosamente.")
    except Exception as e:
        log(f"Aviso al escribir en Step Summary: {e}")


def record_in_expediente(records: List[Dict[str, Any]], dry_run: bool = False):
    """
    Guarda el Historial de Discusiones Resueltas en docs/FechaAgente/<YYYY-MM-DD>/discusiones_atendidas.md
    para trazabilidad continua de la comunidad y casos de estudio.
    """
    if not records:
        return
        
    now = datetime.now(timezone.utc)
    date_str = now.strftime("%Y-%m-%d")
    folder = os.path.join("docs", "FechaAgente", date_str)
    os.makedirs(folder, exist_ok=True)
    file_path = os.path.join(folder, "discusiones_atendidas.md")
    
    lines = []
    if not os.path.isfile(file_path):
        lines.append(f"# Expediente de Discusiones Atendidas — {date_str}\n")
        lines.append("Registro continuo de consultas de la comunidad resueltas por el Agente Centinela.\n")
        
    for r in records:
        lines.append(f"### Discusión #{r['numero']}: {r['titulo']}")
        lines.append(f"- **Autor:** @{r['autor']}")
        lines.append(f"- **Fecha UTC:** {r['fecha']}")
        lines.append(f"- **Idioma:** {r['idioma'].upper()}")
        lines.append(f"- **Escalado:** {r['escalado'] or 'No'}")
        lines.append(f"- **URL del comentario:** {r['url']}")
        lines.append("")
        
    if dry_run:
        log(f"[SIMULACIÓN] Se guardaría expediente histórico en: {file_path}")
        return
        
    try:
        with open(file_path, "a", encoding="utf-8") as f:
            f.write("\n".join(lines) + "\n")
        log(f"Expediente histórico actualizado en: {file_path}")
    except Exception as e:
        log(f"Aviso al guardar expediente histórico: {e}")


def gather_repository_context() -> Dict[str, Any]:
    """Extrae el estado vivo del repositorio para alimentar el contexto del agente."""
    context: Dict[str, Any] = {
        "stack": "TanStack Start / React 19 / Vite 8 / Tailwind CSS v4",
        "arquitectura": "Generación Estática (SSG) / Single Page Application en GitHub Pages sin backend persistente",
        "habilidades": ["01-definir", "02-planificar", "03-construir", "04-verificar", "05-revisar", "06-aprobar"],
        "seguridad": "Secretos gestionados exclusivamente en GitHub Secrets; habilidad 05-revisar en pre-merge"
    }

    for pkg_path in ["portfolio-source/package.json", "../portfolio-source/package.json"]:
        if os.path.isfile(pkg_path):
            try:
                with open(pkg_path, "r", encoding="utf-8") as f:
                    pkg = json.load(f)
                    context["dependencies"] = list(pkg.get("dependencies", {}).keys())
                    context["devDependencies"] = list(pkg.get("devDependencies", {}).keys())
                    break
            except Exception as e:
                log(f"Aviso al leer {pkg_path}: {e}")

    try:
        log_out = run_cmd(["git", "log", "-n", "3", "--oneline"], check=False)
        if log_out:
            context["ultimos_commits"] = log_out.splitlines()
    except Exception:
        pass

    return context


def get_discussion_details(owner: str, repo: str, number: int) -> Dict[str, Any]:
    """Obtiene los detalles y comentarios de una discusión específica."""
    query = """
    query($owner: String!, $name: String!, $num: Int!) {
      repository(owner: $owner, name: $name) {
        discussion(number: $num) {
          id
          number
          title
          body
          url
          author {
            login
          }
          answer {
            id
          }
          category {
            id
            name
            isAnswerable
          }
          comments(last: 15) {
            totalCount
            nodes {
              id
              author {
                login
              }
              body
              createdAt
            }
          }
        }
      }
    }
    """
    res = gh_graphql(query, {"owner": owner, "name": repo, "num": number})
    discussion = res.get("repository", {}).get("discussion")
    if not discussion:
        raise ValueError(f"No se encontró la discusión #{number} en {owner}/{repo}")
    return discussion


def get_open_discussions(owner: str, repo: str, limit: int = 10) -> List[Dict[str, Any]]:
    """Obtiene las discusiones recientes para auditar cuáles requieren respuesta."""
    query = """
    query($owner: String!, $name: String!, $limit: Int!) {
      repository(owner: $owner, name: $name) {
        discussions(first: $limit, orderBy: {field: UPDATED_AT, direction: DESC}) {
          nodes {
            id
            number
            title
            body
            url
            author {
              login
            }
            answer {
              id
            }
            category {
              id
              name
              isAnswerable
            }
            comments(last: 5) {
              totalCount
              nodes {
                id
                author {
                  login
                }
                body
                createdAt
              }
            }
          }
        }
      }
    }
    """
    res = gh_graphql(query, {"owner": owner, "name": repo, "limit": limit})
    return res.get("repository", {}).get("discussions", {}).get("nodes", [])


def needs_response(discussion: Dict[str, Any], force: bool = False) -> Optional[Dict[str, Any]]:
    """
    Evalúa si la discusión o un hilo continuado tiene preguntas sin responder.
    Retorna el comentario o nodo al que se debe responder, o None si ya está atendida.
    """
    comments = discussion.get("comments", {}).get("nodes", [])
    
    if force:
        return comments[-1] if comments else {"body": discussion.get("body", ""), "author": discussion.get("author")}

    if not comments:
        disc_author = discussion.get("author", {}).get("login", "")
        if disc_author and disc_author != OWNER_DEFAULT:
            return {"body": discussion.get("body", ""), "author": discussion.get("author")}
        return None

    last_comment = comments[-1]
    last_author = last_comment.get("author", {}).get("login", "")
    last_body = last_comment.get("body", "")

    if SIGNATURE_MARKER in last_body or SIGNATURE_MARKER_EN in last_body:
        return None

    if last_author == OWNER_DEFAULT:
        return None

    return last_comment


def call_gemini_api(prompt: str, api_key: str) -> Optional[str]:
    """Llama a la API de Gemini utilizando modelos de alta disponibilidad."""
    models = ["gemini-2.5-flash", "gemini-1.5-flash"]
    for model in models:
        url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent?key={api_key}"
        headers = {"Content-Type": "application/json"}
        payload = {
            "contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": {
                "temperature": 0.2,
                "maxOutputTokens": 1500
            }
        }
        req = urllib.request.Request(url, data=json.dumps(payload).encode("utf-8"), headers=headers, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                data = json.loads(resp.read().decode("utf-8"))
                candidates = data.get("candidates", [])
                if candidates:
                    parts = candidates[0].get("content", {}).get("parts", [])
                    if parts and "text" in parts[0]:
                        return parts[0]["text"].strip()
        except Exception as e:
            log(f"Fallo al invocar modelo {model}: {e}. Probando alternativa...")
    return None


def synthesize_project_response(discussion_title: str, query_text: str, author: str, context: Dict[str, Any], lang: str = "es", escalation: Optional[str] = None) -> str:
    """
    Motor de síntesis contextual bilingüe anclado en la arquitectura del portafolio.
    """
    q_lower = (discussion_title + " " + query_text).lower()

    if lang == "en":
        # Respuesta en Inglés
        if escalation:
            return f"""Hello @{author}! Thank you for bringing this to our attention.

⚠️ **Notice:** We have detected that this inquiry touches on a critical topic ({escalation}). This issue has been automatically escalated to @{OWNER_DEFAULT} via our internal security and bug tracking pipeline for detailed inspection.

In the meantime, feel free to share any reproducible logs or additional context."""

        if any(k in q_lower for k in ["secret", ".env", "gitleaks", "git-secrets", "vault", "doppler", "token", "leak"]):
            return f"""Hi @{author}! Happy to clarify the technical differences between these tools and how they apply to the architecture of this portfolio:

### 1. `.env` vs `git-secrets` vs `gitleaks` vs `Vault / Doppler`

The fundamental difference lies in **which stage of the data lifecycle each tool operates** (Defense-in-Depth):

| Tool | Architectural Role | Execution Environment | Mechanism | When to use |
| :--- | :--- | :--- | :--- | :--- |
| **`.env`** | Runtime local configuration | Local dev machine | Plain-text key-value file excluded via `.gitignore`. | Local development for non-critical env vars (`PORT`, local URLs). **Never** for production or master keys. |
| **`git-secrets`** | Client-side git hook | Local (`pre-commit`) | Git hook intercepting commits matching regex or AWS patterns. | First line of defense on developer workstations to prevent accidental secret commits. |
| **`gitleaks`** | Static audit (SAST) & CI gate | Local and **GitHub Actions** | Ultra-fast Go binary scanning entropy and 150+ token signatures across commit diffs and full `git log`. | **Essential in CI/CD**: Blocks Pull Requests before merge if someone attempts to push leaked credentials. |
| **Vault / Doppler** | Centralized secrets manager (KMS) | Cloud / Dedicated service | Encrypted storage (AES-256) with RBAC, ephemeral tokens, dynamic rotation, and access audit logs. | Production environments and microservices where database credentials rotate periodically and must never touch disk. |

---

### 2. How this applies to this Portfolio ([`Luics415.github.io`](https://github.com/Luics415/Luics415.github.io))

1. **No `.env` in production**: The portfolio is a static site built with **TanStack Start and Vite**, deployed directly to GitHub Pages without a persistent Node/Python runtime backend. No private keys are compiled into the client bundle.
2. **Secrets in GitHub Actions**: Deployment and workflow tokens live exclusively in **GitHub Secrets** and are injected as ephemeral environment variables during CI/CD runs.
3. **Pre-Merge Audit (Skill 05 - Revisar)**: Before any Pull Request is approved and merged, our automated orchestrator runs the review skill to verify zero secret exposure in commits.
4. **Why Vault/Doppler is not needed here**: Heavy secrets managers are designed for enterprise backends with rotating DB credentials every 15 minutes; for a static public SSG/SPA, GitHub Secrets + static scanning via `gitleaks` is the optimal, cost-efficient security standard."""

        return f"""Hi @{author}! Thanks for reaching out about the project.

This official portfolio operates under the following technical stack:
- **Frontend Core:** TanStack Start, React 19, Tailwind CSS v4, and Vite.
- **Delivery Workflow:** 6-phase atomic orchestrator (`01-definir` through `06-aprobar`).
- **Hosting:** Static generation deployed to GitHub Pages via GitHub Actions.

For detailed architecture guidelines, please check [`README.md`](https://github.com/Luics415/Luics415.github.io/blob/main/README.md) and [`AGENTS.md`](https://github.com/Luics415/Luics415.github.io/blob/main/AGENTS.md)."""

    # Respuesta en Español
    if escalation:
        return f"""¡Hola @{author}! Gracias por reportar esta situación.

⚠️ **Aviso de Escalamiento:** Hemos identificado que esta consulta refiere a un tema crítico ({escalation}). El caso ha sido escalado automáticamente a @{OWNER_DEFAULT} mediante nuestro sistema interno de seguimiento para su revisión prioritaria.

Mientras tanto, puedes compartir registros de consola o pasos de reproducción adicionales si dispones de ellos."""

    if any(k in q_lower for k in ["secreto", ".env", "gitleaks", "git-secrets", "vault", "doppler", "token", "fuga"]):
        return f"""¡Hola @{author}! Con gusto profundizamos en la comparativa técnica entre estas herramientas y cómo se aplican en la arquitectura real de este portafolio:

### 1. `.env` vs `git-secrets` vs `gitleaks` vs `Vault / Doppler`

La diferencia principal radica en **en qué fase del ciclo de vida del dato actúa cada herramienta** dentro de una estrategia de Defensa en Profundidad (*Defense-in-Depth*):

| Herramienta | Rol Arquitectural | Dónde se ejecuta | Mecanismo | Cuándo usarlo |
| :--- | :--- | :--- | :--- | :--- |
| **`.env`** | Configuración local en runtime | Máquina local del dev | Archivo plano (`KEY=VALUE`) excluido en `.gitignore`. | Desarrollo local para variables de entorno no críticas (`PORT`, URLs locales). **Nunca** para claves maestras ni producción, ya que no cifra ni audita. |
| **`git-secrets`** | Prevención en hook de cliente | Local (`pre-commit`) | Hook de Git que intercepta el commit si coincide con patrones Regex o claves AWS (`AKIA...`). | Como primera línea de defensa en la estación del desarrollador para evitar crear commits con credenciales por error. |
| **`gitleaks`** | Auditoría estática (SAST) y compuerta CI/CD | Local y en **GitHub Actions** | Binario en Go ultrarrápido que analiza entropía y más de 150 firmas de tokens en diffs y en todo el historial `git log`. | **Indispensable en CI/CD**: Bloquea Pull Requests antes del merge si alguien intenta filtrar credenciales al repositorio remoto. |
| **Vault / Doppler** | Gestor centralizado de secretos (KMS) | Servicio Cloud / Dedicado | Almacén cifrado (AES-256) con RBAC, tokens efímeros, rotación automática de claves y auditoría de accesos. | En producción y microservicios donde las credenciales deben rotar periódicamente y nunca residir en archivos planos en disco. |

---

### 2. ¿Cómo se aplica esto directamente a este Portafolio?

En este proyecto ([`Luics415.github.io`](https://github.com/Luics415/Luics415.github.io)):

1. **Sin `.env` en producción**: El portafolio es un sitio web estático generado con **TanStack Start y Vite** desplegado en GitHub Pages. Al no tener un servidor persistente Node/Python en runtime, **no debe compilarse ninguna credencial privada dentro del bundle de cliente**.
2. **Secretos en GitHub Actions**: Las credenciales de automatización, tokens y despliegues residen exclusivamente en **GitHub Secrets** (`secrets.GITHUB_TOKEN`, `secrets.GEMINI_API_KEY`) y se inyectan como variables de entorno efímeras en los runners de GitHub Actions.
3. **Auditoría Pre-Merge (Habilidad 05 - Revisar)**: Antes de aprobar y fusionar cualquier cambio o Pull Request, el pipeline orquestador ejecuta la fase de revisión para certificar la ausencia total de tokens expuestos en commits o código compilado.
4. **Por qué no usamos Vault/Doppler aquí**: Gestores como HashiCorp Vault o Doppler están diseñados para arquitecturas complejas con rotación dinámica de claves de bases de datos cada 15 minutos; para un portafolio SSG/SPA público en GitHub Pages, GitHub Secrets y herramientas de escaneo estático como `gitleaks` cubren el estándar de seguridad óptimo sin añadir sobrecostos de infraestructura."""

    return f"""¡Hola @{author}! Gracias por tu consulta sobre el proyecto.

Actualmente el portafolio oficial opera bajo la siguiente arquitectura técnica:
- **Core de Frontend:** TanStack Start, React 19, Tailwind CSS v4 y Vite.
- **Flujo de Entrega:** Modelo orquestado de 6 fases atómicas (`01-definir` a `06-aprobar`).
- **Despliegue:** Generación estática alojada en GitHub Pages mediante GitHub Actions.

Para revisar los detalles específicos del código o los estándares de arquitectura, puedes consultar la documentación técnica en [`README.md`](https://github.com/Luics415/Luics415.github.io/blob/main/README.md) y [`AGENTS.md`](https://github.com/Luics415/Luics415.github.io/blob/main/AGENTS.md)."""


def generate_response(discussion: Dict[str, Any], target_comment: Dict[str, Any], context: Dict[str, Any], lang: str, escalation: Optional[str] = None) -> str:
    """Genera la respuesta adaptada mediante LLM (Gemini) o motor contextual bilingüe."""
    title = discussion.get("title", "")
    author = target_comment.get("author", {}).get("login", "") or discussion.get("author", {}).get("login", "")
    query_text = target_comment.get("body", "")

    gemini_key = os.environ.get("GEMINI_API_KEY", "").strip()
    if gemini_key:
        log(f"GEMINI_API_KEY detectada. Generando respuesta contextual mediante LLM en idioma: {lang.upper()}...")
        target_lang_desc = "English" if lang == "en" else "Spanish"
        system_prompt = f"""You are the Autonomous Sentinel Agent for Luis Rivera's (@{OWNER_DEFAULT}) portfolio repository (Luics415/Luics415.github.io).
Respond strictly in {target_lang_desc} with a pedagogical, professional and technical tone.

Repository Context:
- Architecture: {context.get('arquitectura')}
- Stack: {context.get('stack')}
- Security: {context.get('seguridad')}

User inquiry (@{author}):
Title: {title}
Body: {query_text}

Requirements:
1. Directly answer the question with technical depth.
2. Specifically anchor your answer to this repository (TanStack Start, GitHub Pages, GitHub Secrets).
3. If an escalation ({escalation}) is present, acknowledge it clearly.
"""
        generated = call_gemini_api(system_prompt, gemini_key)
        if generated:
            return generated

    log(f"Generando respuesta utilizando el motor contextual integrado ({lang.upper()})...")
    return synthesize_project_response(title, query_text, author, context, lang=lang, escalation=escalation)


def post_reply(discussion_id: str, body: str, reply_to_id: Optional[str] = None, dry_run: bool = False) -> Optional[str]:
    """Publica la respuesta en la discusión sin marcarla como 'answer'."""
    if dry_run:
        log("Modo DRY-RUN activo. Vista previa de la respuesta:")
        print("--------------------------------------------------")
        print(body)
        print("--------------------------------------------------")
        return "https://github.com/Luics415/Luics415.github.io/discussions/dry-run-comment-id"

    mutation = """
    mutation($discussionId: ID!, $body: String!) {
      addDiscussionComment(input: {discussionId: $discussionId, body: $body}) {
        comment {
          id
          url
          createdAt
        }
      }
    }
    """
    res = gh_graphql(mutation, {"discussionId": discussion_id, "body": body})
    comment = res.get("addDiscussionComment", {}).get("comment", {})
    return comment.get("url")


def main():
    parser = argparse.ArgumentParser(description="Agente Centinela Autónomo Bilingüe de GitHub Discussions")
    parser.add_argument("--owner", default=OWNER_DEFAULT, help="Propietario del repositorio")
    parser.add_argument("--repo", default=REPO_DEFAULT, help="Nombre del repositorio")
    parser.add_argument("--discussion-number", type=int, help="Número de discusión específico")
    parser.add_argument("--dry-run", action="store_true", help="Simular sin publicar comentarios ni crear issues")
    parser.add_argument("--force", action="store_true", help="Forzar respuesta omitiendo comprobación de duplicados")
    args = parser.parse_args()

    log(f"Iniciando centinela para {args.owner}/{args.repo}...")
    context = gather_repository_context()

    if args.discussion_number:
        discussions = [get_discussion_details(args.owner, args.repo, args.discussion_number)]
    else:
        discussions = get_open_discussions(args.owner, args.repo)

    log(f"Analizando {len(discussions)} discusión(es)...")
    records_atendidos = []

    for disc in discussions:
        disc_num = disc.get("number")
        target_comment = needs_response(disc, force=args.force)

        if not target_comment:
            log(f"Discusión #{disc_num} ('{disc.get('title')}') está al día o ya respondida. Omitiendo.")
            continue

        author = target_comment.get("author", {}).get("login", "") or disc.get("author", {}).get("login", "")
        title = disc.get("title", "")
        query_text = target_comment.get("body", "")

        # 1. Detección de Idioma
        lang = detect_language(title + " " + query_text)
        log(f"Procesando Discusión #{disc_num} ('{title}') | Autor: @{author} | Idioma detectado: {lang.upper()}...")

        # 2. Detección y Escalamiento de Seguridad / Bugs
        escalation_data = detect_security_or_bug_escalation(title, query_text)
        escalation_cat = escalation_data[0] if escalation_data else None

        # 3. Generación de Respuesta
        base_response = generate_response(disc, target_comment, context, lang=lang, escalation=escalation_cat)

        # 4. Inyección del Pie con Notificación Nivel 1 (Mención y Enlace de Validación)
        disc_url = disc.get("url", f"https://github.com/{args.owner}/{args.repo}/discussions/{disc_num}")
        if lang == "en":
            footer = f"""

---
> {SIGNATURE_MARKER_EN} based on repository architecture.*  
> 🔔 **Notice for @{args.owner}:** Response ready for review. You may [verify and mark as answer here]({disc_url})."""
        else:
            footer = f"""

---
> {SIGNATURE_MARKER} en base a la arquitectura del repositorio.*  
> 🔔 **Aviso para @{args.owner}:** Respuesta lista para tu revisión. Puedes [validarla y marcarla como definitiva aquí]({disc_url})."""

        full_response = base_response + footer

        # 5. Publicación en GitHub Discussions
        url = post_reply(
            discussion_id=disc.get("id"),
            body=full_response,
            reply_to_id=target_comment.get("id"),
            dry_run=args.dry_run
        )

        if url:
            log(f"Comentario publicado con éxito en #{disc_num}: {url}")

            # 6. Escalamiento en GitHub Issues si aplica
            if escalation_cat:
                escalate_issue_to_github(
                    owner=args.owner,
                    repo=args.repo,
                    disc_number=disc_num,
                    title=title,
                    author=author,
                    comment_url=url,
                    category=escalation_cat,
                    text=query_text,
                    dry_run=args.dry_run
                )

            # 7. Notificación Nivel 3 (Telegram / Discord)
            send_level_3_notifications(
                owner=args.owner,
                repo=args.repo,
                disc_number=disc_num,
                title=title,
                author=author,
                comment_url=url,
                lang=lang
            )

            records_atendidos.append({
                "numero": disc_num,
                "titulo": title,
                "autor": author,
                "idioma": lang,
                "escalado": escalation_cat,
                "url": url,
                "fecha": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")
            })

    # 8. Notificación Nivel 2 (GitHub Actions Step Summary)
    write_step_summary(records_atendidos)

    # 9. Historial en Expediente (docs/FechaAgente/)
    record_in_expediente(records_atendidos, dry_run=args.dry_run)

    log(f"Ejecución completada. Total de respuestas gestionadas: {len(records_atendidos)}.")


if __name__ == "__main__":
    main()
